void settings_menu_app_ui_event_actions(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    //lv_obj_t * target = lv_event_get_target(e);
    uint32_t        child_cnt = lv_obj_get_child_cnt(ui_SettingMenuIndex);
    uint32_t        child_id = get_list_child_focused_id(ui_SettingMenuIndex,child_cnt);
    lv_obj_t *      get_focus_obj = NULL;
    lv_obj_t *      pre_focus_obj = NULL;

    __inf("settings_menu_app_ui_event_actions 00 =%d\r\n",event_code);

    switch (event_code)
    {
        case LV_EVENT_SCREEN_LOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_add_obj(lv_group_get_default(),obj);
                    lv_group_focus_obj(obj);
                    }

                }
            break;

        case LV_EVENT_SCREEN_UNLOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_remove_obj(obj);
                    }
                }
            break;

        case LV_EVENT_KEY:
            {
                uint32_t        key = lv_event_get_key(e);

                __inf("settings_menu_app_ui_event_actions111 LV_EVENT_KEY:%d\r\n",key);

                if (key == LV_KEY_UP) {
                    //__inf("LV_KEY_UP,child_id:%d,child_cnt:%d\r\n",child_id,child_cnt);
                    if (child_id != 0) {
                        pre_focus_obj       = lv_obj_get_child(ui_SettingMenuIndex,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_t *      pre_focus_obj1 = lv_obj_get_child(pre_focus_obj,1);

                        lv_label_set_long_mode(pre_focus_obj1,LV_LABEL_LONG_CLIP);



                        get_focus_obj       = lv_obj_get_child(ui_SettingMenuIndex,child_id - 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                        if ((child_id - 1) == 0) {
                            lv_obj_scroll_to_y(ui_SettingMenuIndex,0,LV_ANIM_OFF);
                            }
                        else {
                            lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                            }

                        lv_obj_t *      get_focus_obj1 = lv_obj_get_child(get_focus_obj,1);

                        lv_label_set_long_mode(get_focus_obj1,LV_LABEL_LONG_SCROLL_CIRCULAR);

                        app_fp_play_tts_menu(lv_label_get_text(get_focus_obj1));
                        }
                    else {
                        pre_focus_obj       = lv_obj_get_child(ui_SettingMenuIndex,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_t *      pre_focus_obj1 = lv_obj_get_child(pre_focus_obj,1);

                        lv_label_set_long_mode(pre_focus_obj1,LV_LABEL_LONG_CLIP);

                        get_focus_obj       = lv_obj_get_child(ui_SettingMenuIndex,child_cnt - 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                        //__inf("get_focus_obj :%d\r\n",lv_obj_has_state(get_focus_obj, LV_STATE_FOCUSED));
                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                        lv_obj_t *      get_focus_obj1 = lv_obj_get_child(get_focus_obj,1);

                        lv_label_set_long_mode(get_focus_obj1,LV_LABEL_LONG_SCROLL_CIRCULAR);

                        app_fp_play_tts_menu(lv_label_get_text(get_focus_obj1));
                        }

                    }
                else if (key == LV_KEY_DOWN) {

                    if (child_id != child_cnt - 1) {
                        pre_focus_obj       = lv_obj_get_child(ui_SettingMenuIndex,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_t *      pre_focus_obj1 = lv_obj_get_child(pre_focus_obj,1);

                        lv_label_set_long_mode(pre_focus_obj1,LV_LABEL_LONG_CLIP);

                        get_focus_obj       = lv_obj_get_child(ui_SettingMenuIndex,child_id + 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                        lv_obj_t *      get_focus_obj1 = lv_obj_get_child(get_focus_obj,1);

                        lv_label_set_long_mode(get_focus_obj1,LV_LABEL_LONG_SCROLL_CIRCULAR);

                        app_fp_play_tts_menu(lv_label_get_text(get_focus_obj1));
                        }
                    else {
                        pre_focus_obj       = lv_obj_get_child(ui_SettingMenuIndex,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_t *      pre_focus_obj1 = lv_obj_get_child(pre_focus_obj,1);

                        lv_label_set_long_mode(pre_focus_obj1,LV_LABEL_LONG_CLIP);

                        get_focus_obj       = lv_obj_get_child(ui_SettingMenuIndex,0);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                        lv_obj_scroll_to_y(ui_SettingMenuIndex,0,LV_ANIM_OFF);
                        lv_obj_t *      get_focus_obj1 = lv_obj_get_child(get_focus_obj,1);

                        lv_label_set_long_mode(get_focus_obj1,LV_LABEL_LONG_SCROLL_CIRCULAR);

                        app_fp_play_tts_menu(lv_label_get_text(get_focus_obj1));
                        }

                    }
                else if (key == LV_KEY_LEFT) {

                    }
                else if (key == LV_KEY_DEL) {
                    alv_am_app_exit_action(NULL,"settings",NULL);
                    alv_am_app_enter_action(NULL,"home_fp",NULL);
                    }
                else if ((key == LV_KEY_ESC) || (key == LV_KEY_ENTER)) {
                    alv_am_win_enter(NULL,settings_label_param_array[child_id].enter_subwin_name,NULL);
                    }
                else if (key == LV_KEY_END)
                    alv_am_app_exit_action_all();
                }
            break;

        default:
            break;
        }


}


